package com.aveycole.agentlooper;

import android.graphics.*;
import android.view.*;
import java.util.*;

/** Code-drawn controls, large touch targets, no platform knob focus outlines. */
public final class LooperView extends View {
    static final int BG=0xff0c0f13,PANEL=0xff171c22,LINE=0xff2b333b,MUTED=0xff87949f,WHITE=0xffeef3f5,MINT=0xff85f2c3,GOLD=0xfff4c776,RED=0xffff7069;
    final MainActivity host;
    final LoopEngine engine;
    final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);
    final ArrayList<Hit> hits=new ArrayList<>();
    final IdentityHashMap<LoopEngine.Layer,Float> zoom=new IdentityHashMap<>(),pan=new IdentityHashMap<>();
    float density,scroll,total,viewport;
    float downX,downY,lastY,startValue,startPan,startPinch;
    long downAt;
    Hit active;
    boolean dragged,pinching;
    static class Hit{RectF r;Runnable tap;int bank=-1,action=-1,knob=-1,handle;LoopEngine.Layer layer;Hit(RectF rect,Runnable action){r=rect;tap=action;}}
    public LooperView(MainActivity a){super(a);host=a;engine=a.engine;density=getResources().getDisplayMetrics().density;setFocusable(true);setContentDescription("Agent Looper. Two audio loopers. Long press a transport to assign MIDI.");}
    void text(Canvas c,String s,float x,float y,float size,int color,boolean bold){p.setColor(color);p.setStyle(Paint.Style.FILL);p.setTextSize(size);p.setTypeface(bold?Typeface.create("sans-serif",Typeface.BOLD):Typeface.create("sans-serif",Typeface.NORMAL));c.drawText(s,x,y,p);}
    RectF rect(float x,float y,float w,float h){return new RectF(x,y,x+w,y+h);}
    void box(Canvas c,RectF r,int color){p.setStyle(Paint.Style.FILL);p.setColor(color);c.drawRoundRect(r,7,7,p);}
    Hit button(Canvas c,String label,float x,float y,float w,float h,int color,boolean lit,Runnable action){RectF r=rect(x,y,w,h);box(c,r,PANEL);if(lit)box(c,r,Color.argb(24,Color.red(color),Color.green(color),Color.blue(color)));p.setColor(LINE);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1);c.drawRoundRect(r,7,7,p);p.setStyle(Paint.Style.FILL);p.setTextSize(h<40?10:11);p.setTypeface(Typeface.create("sans-serif-medium",0));p.setColor(lit?color:WHITE);c.drawText(label,x+(w-p.measureText(label))/2,y+h/2+4,p);Hit hit=new Hit(r,action);hits.add(hit);return hit;}
    @Override protected void onDraw(Canvas canvas){super.onDraw(canvas);canvas.drawColor(BG);canvas.save();canvas.translate(getPaddingLeft(),getPaddingTop());canvas.scale(density,density);float w=(getWidth()-getPaddingLeft()-getPaddingRight())/density;viewport=(getHeight()-getPaddingTop()-getPaddingBottom())/density;canvas.translate(0,-scroll);hits.clear();text(canvas,"Agent Looper",16,33,w<500?23:27,MINT,true);float y=49;button(canvas,"AUDIO",16,y,70,40,MINT,false,host::audioMenu);button(canvas,"FILES",92,y,65,40,MINT,false,host::fileMenu);button(canvas,"MIDI",163,y,62,40,MINT,false,()->host.midi.menu());button(canvas,String.format(Locale.US,"%.0f BPM",engine.bpm),231,y,Math.max(70,Math.min(100,w-247)),40,MINT,false,host::timing);y+=48;button(canvas,"CLICK",16,y,70,36,MINT,engine.click,()->{engine.click=!engine.click;host.saveLocal();});button(canvas,"COUNT "+engine.countIn,92,y,96,36,MINT,engine.countIn>0,()->host.choice("Count-in",new String[]{"OFF","1 MEASURE","2 MEASURES"},engine.countIn,n->engine.countIn=n));float meterX=200;meter(canvas,meterX,y+7,Math.max(30,w-216),engine.inputPeak,engine.outputPeak);y+=51;
        synchronized(engine){if(w>=700){float bw=(w-44)/2;float a=bank(canvas,0,16,y,bw),b=bank(canvas,1,28+bw,y,bw);y=Math.max(a,b);}else{y=bank(canvas,0,16,y,w-32)+20;y=bank(canvas,1,16,y,w-32);}}text(canvas,engine.message==null?"":engine.message,16,y+25,11,MUTED,false);total=y+55;scroll=Math.max(0,Math.min(scroll,Math.max(0,total-viewport)));canvas.restore();postInvalidateDelayed(33);}
    void meter(Canvas c,float x,float y,float w,float in,float out){for(int i=0;i<24;i++){float bw=(w-36)/24;p.setColor(i/24f<in?MINT:LINE);c.drawRect(x+30+i*bw,y,x+30+i*bw+bw-2,y+7,p);p.setColor(i/24f<out?(out>1?RED:GOLD):LINE);c.drawRect(x+30+i*bw,y+13,x+30+i*bw+bw-2,y+20,p);}text(c,"IN",x,y+7,9,MUTED,false);text(c,"OUT",x,y+20,9,MUTED,false);}
    float bank(Canvas c,int index,float x,float y,float w){LoopEngine.Bank b=engine.banks[index];int color=index==0?MINT:GOLD;String name=index==0?"A":"B";text(c,name+" / LOOPER",x,y+17,15,color,true);text(c,b.state(),x+w-80,y+17,14,color,false);Hit select=new Hit(rect(x,y,w,26),()->host.selected=index);hits.add(select);y+=29;float waveHeight=70;LoopEngine.Layer first=b.layers.isEmpty()?null:b.layers.get(0);wave(c,first,x,y,w,waveHeight,b.frame,color,false);y+=waveHeight+8;button(c,(b.sync?"SYNC":"FREE")+" · "+engine.bars+" BAR"+(engine.bars==1?"":"S"),x,y,w*.48f,36,color,b.sync,()->host.routing(index));button(c,"START · "+new String[]{"NOW","MEASURE",index==0?"B LOOP":"A LOOP"}[b.quantize],x+w*.5f,y,w*.5f,36,color,false,()->host.routing(index));y+=43;button(c,"INPUT · "+new String[]{"LIVE","A","LIVE + A"}[b.inputMode],x,y,w*.43f,36,color,false,()->host.routing(index));Hit auto=button(c,"AUTO OD",x+w*.45f,y,w*.26f,36,color,b.auto,()->host.transport(index,4));auto.bank=index;auto.action=4;button(c,b.warpPending?"WARP…":"WARP",x+w*.73f,y,w*.27f,36,color,b.warp||b.warpPending,()->{engine.toggleWarp(index);host.saveLocal();});y+=44;float tw=(w-18)/4;String[] labels={b.signalArmed?"ARMED":b.recording?"FINISH":"● REC","+ DUB",b.playAt>=0?"ARMED":b.playing?"Ⅱ STOP":"▶ PLAY","UNDO"};for(int i=0;i<4;i++){final int action=i;Hit h=button(c,labels[i],x+i*(tw+6),y,tw,48,i==0?RED:color,i==0?b.recording:i==1?b.overdub&&b.recording:i==2?b.playing:false,()->host.transport(index,action));h.bank=index;h.action=i;}y+=59;for(int i=0;i<b.layers.size();i++){LoopEngine.Layer l=b.layers.get(i);float height=l.expanded?350:132;box(c,rect(x,y,w,height),PANEL);p.setColor(color);c.drawRect(x,y+8,x+3,y+height-8,p);text(c,String.format(Locale.US,"%02d",i+1)+"  "+l.name,x+12,y+25,12,color,true);float bx=x+w-178;button(c,"M",bx,y+6,32,36,color,l.mute,()->{l.mute=!l.mute;host.saveLocal();});button(c,"S",bx+36,y+6,32,36,color,l.solo,()->{l.solo=!l.solo;host.saveLocal();});button(c,l.expanded?"EDIT ▴":"EDIT ▾",bx+72,y+6,62,36,color,l.expanded,()->l.expanded=!l.expanded);button(c,"×",bx+138,y+6,32,36,color,false,()->{engine.remove(index,l);host.saveLocal();});wave(c,l,x+12,y+49,w-24,69,b.frame,color,true);if(l.expanded){String[] names={"STRETCH","PITCH","FILTER","LEVEL","PAN"};float kw=(w-16)/5;for(int k=0;k<5;k++)knob(c,l,k,names[k],x+8+k*kw,y+128,kw,color);button(c,"REV",x+12,y+245,55,42,color,l.reverse,()->l.reverse=!l.reverse);button(c,"½",x+73,y+245,45,42,color,false,()->{l.end=l.start+Math.max(1,(l.end-l.start)/2);host.saveLocal();});button(c,"×2",x+124,y+245,45,42,color,false,()->{l.end=Math.min(l.audio.length,l.start+2*(l.end-l.start));host.saveLocal();});button(c,"FULL",x+175,y+245,55,42,color,false,()->{l.start=0;l.end=l.audio.length/2;host.saveLocal();});text(c,String.format(Locale.US,"%.2f s",l.frames()/(double)LoopEngine.RATE),x+w-73,y+271,11,MUTED,false);}if(l.expanded)button(c,l.mode==0?"GRANULAR · INDEPENDENT":"REPITCH · TAPE",x+12,y+298,w-24,39,color,false,()->{l.mode=1-l.mode;host.saveLocal();});y+=height+10;}return y;}
    void knob(Canvas c,LoopEngine.Layer l,int kind,String name,float x,float y,float w,int color){double value=knobValue(l,kind);float ratio=kind==0?(float)((value-.5)/1.5):kind==1?(float)((value+12)/24):kind==2?(float)(Math.log(value/40)/Math.log(500)):kind==3?(float)(value/1.5):(float)((value+1)/2);float cx=x+w/2,cy=y+50,r=Math.min(24,w*.35f);text(c,name,x+(w-name.length()*5)/2,y+8,9,MUTED,false);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(3);p.setStrokeCap(Paint.Cap.ROUND);RectF ring=rect(cx-r,cy-r,r*2,r*2);p.setColor(LINE);c.drawArc(ring,135,270,false,p);p.setColor(color);c.drawArc(ring,135,Math.max(.1f,270*ratio),false,p);p.setStyle(Paint.Style.FILL);p.setColor(0xff293139);c.drawCircle(cx,cy,r-5,p);double a=(135+270*ratio)*Math.PI/180;p.setColor(color);p.setStrokeWidth(2);c.drawLine(cx+(float)Math.cos(a)*8,cy+(float)Math.sin(a)*8,cx+(float)Math.cos(a)*(r-9),cy+(float)Math.sin(a)*(r-9),p);p.setStrokeCap(Paint.Cap.BUTT);String label=kind==0?String.format(Locale.US,"%.2f×",value):kind==1?String.format(Locale.US,"%+.1f",value):kind==2?(value>=1000?String.format(Locale.US,"%.1fk",value/1000):String.format(Locale.US,"%.0f",value)):kind==3?String.format(Locale.US,"%.0f%%",value*100):String.format(Locale.US,"%+.0f",value*100);p.setTextSize(11);text(c,label,cx-p.measureText(label)/2,y+94,11,WHITE,false);Hit h=new Hit(rect(x,y,w,110),null);h.layer=l;h.knob=kind;hits.add(h);}
    double knobValue(LoopEngine.Layer l,int k){return k==0?l.stretch:k==1?l.pitch:k==2?l.cutoff:k==3?l.gain:l.pan;}
    void knobSet(LoopEngine.Layer l,int k,double v){if(k==0)l.stretch=Math.max(.5,Math.min(2,v));if(k==1)l.pitch=Math.max(-12,Math.min(12,v));if(k==2)l.cutoff=Math.max(40,Math.min(20000,v));if(k==3)l.gain=Math.max(0,Math.min(1.5,v));if(k==4)l.pan=Math.max(-1,Math.min(1,v));}
    float zoom(LoopEngine.Layer l){return zoom.containsKey(l)?zoom.get(l):1;}
    float pan(LoopEngine.Layer l){return pan.containsKey(l)?pan.get(l):0;}
    void wave(Canvas c,LoopEngine.Layer l,float x,float y,float w,float h,long frame,int color,boolean edit){RectF r=rect(x,y,w,h);box(c,r,BG);c.save();c.clipRect(r);p.setStrokeWidth(1);p.setColor(LINE);for(int i=1;i<12;i++)c.drawLine(x+w*i/12,y,x+w*i/12,y+h,p);if(l!=null){float z=edit?zoom(l):1,view=edit?pan(l):0,peak=l.peak();float visual=peak>1e-8?Math.min(1000000,.9f/peak):1;float length=l.audio.length/2f;for(int pixel=0;pixel<w;pixel+=2){float begin=view+pixel/w/z,end=view+(pixel+2)/w/z;int from=Math.max(0,(int)(begin*l.envelope.length)),to=Math.min(l.envelope.length-1,Math.max(from,(int)(end*l.envelope.length)));float v=0;for(int j=from;j<=to;j++)v=Math.max(v,l.envelope[j]);float hh=Math.max(.5f,Math.min(1,v*visual)*h*.44f);p.setColor(color);c.drawRect(x+pixel,y+h/2-hh,x+pixel+2,y+h/2+hh,p);}LoopEngine.Bank owner=engine.banks[0].layers.contains(l)?engine.banks[0]:engine.banks[1];double pos=owner.warp?LoopEngine.mod(frame-owner.origin,owner.warpFrames)*(l.end-l.start)/owner.warpFrames:LoopEngine.mod(frame-l.offset,l.frames())/l.stretch*(l.mode==1?Math.pow(2,l.pitch/12):1);if(l.reverse)pos=Math.max(1,l.end-l.start)-1-pos;float cursor=x+(float)((l.start+pos)/length-view)*w*z;p.setColor(WHITE);c.drawLine(cursor,y+4,cursor,y+h-4,p);if(edit){float left=x+(l.start/length-view)*w*z,right=x+(l.end/length-view)*w*z;p.setColor(Color.argb(22,Color.red(color),Color.green(color),Color.blue(color)));c.drawRect(left,y,right,y+h,p);p.setColor(color);c.drawRect(left-4,y,left+4,y+h,p);c.drawRect(right-4,y,right+4,y+h,p);Hit hit=new Hit(r,null);hit.layer=l;hit.handle=3;hits.add(hit);}}c.restore();}
    float tx(MotionEvent e){return (e.getX()-getPaddingLeft())/density;}
    float ty(MotionEvent e){return (e.getY()-getPaddingTop())/density+scroll;}
    @Override public boolean onTouchEvent(MotionEvent e){float x=tx(e),y=ty(e);if(e.getActionMasked()==MotionEvent.ACTION_DOWN){downX=x;downY=y;lastY=e.getY()/density;downAt=System.currentTimeMillis();dragged=pinching=false;active=null;for(int i=hits.size()-1;i>=0;i--)if(hits.get(i).r.contains(x,y)){active=hits.get(i);break;}if(active!=null&&active.layer!=null){LoopEngine.Layer l=active.layer;if(active.knob>=0)startValue=(float)knobValue(l,active.knob);else{float size=l.audio.length/2f,z=zoom(l),view=pan(l);float a=active.r.left+(l.start/size-view)*active.r.width()*z,b=active.r.left+(l.end/size-view)*active.r.width()*z;active.handle=Math.abs(x-a)<22?1:Math.abs(x-b)<22?2:3;startPan=pan(l);}}return true;}if(e.getActionMasked()==MotionEvent.ACTION_POINTER_DOWN&&e.getPointerCount()==2&&active!=null&&active.layer!=null&&active.knob<0){startPinch=distance(e);startValue=zoom(active.layer);pinching=true;return true;}if(e.getActionMasked()==MotionEvent.ACTION_MOVE){float delta=y-downY;if(Math.abs(delta)>4||Math.abs(x-downX)>4)dragged=true;if(pinching&&e.getPointerCount()>1){zoom.put(active.layer,Math.max(1,Math.min(32,startValue*distance(e)/Math.max(1,startPinch))));return true;}if(active!=null&&active.layer!=null){LoopEngine.Layer l=active.layer;if(active.knob>=0){double movement=(downY-y)/160;int k=active.knob;knobSet(l,k,k==2?startValue*Math.pow(500,movement):startValue+movement*(k==0?1.5:k==1?24:k==3?1.5:2));}else{float z=zoom(l),length=l.audio.length/2f;int frame=(int)((pan(l)+(x-active.r.left)/active.r.width()/z)*length);if(active.handle==1)l.start=Math.max(0,Math.min(l.end-1,frame));else if(active.handle==2)l.end=Math.max(l.start+1,Math.min(l.audio.length,frame));else pan.put(l,Math.max(0,Math.min(1-1/z,startPan-(x-downX)/active.r.width()/z)));}}else{float py=e.getY()/density;scroll=Math.max(0,Math.min(Math.max(0,total-viewport),scroll+lastY-py));lastY=py;}return true;}if(e.getActionMasked()==MotionEvent.ACTION_UP){if(active!=null&&!dragged&&!pinching){if(active.bank>=0&&active.action>=0&&System.currentTimeMillis()-downAt>550)host.learn(active.bank,active.action);else if(active.tap!=null)active.tap.run();else if(active.layer!=null&&active.knob>=0&&System.currentTimeMillis()-downAt>550){int k=active.knob;knobSet(active.layer,k,k==0||k==3?1:k==2?20000:0);}}if(active!=null&&active.layer!=null)host.saveLocal();active=null;performClick();return true;}return true;}
    float distance(MotionEvent e){return (float)Math.hypot(e.getX(0)-e.getX(1),e.getY(0)-e.getY(1));}
    @Override public boolean performClick(){super.performClick();return true;}
}
